413	void LiaStarExtension::eagerCheckStar(Node literal, Node lambda)
414	{
415	  // Eager reduction: compute every cone of p up front and emit the exact
416	  // equivalence `literal = star`. Each literal is reduced at most once.
417	  if (std::find(
418	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
419	      != d_processedStarTerms.end())
420	  {
421	    return;
422	  }
423	  // Normalize p to DNF and render each disjunct as a Normaliz constraint matrix.
424	  std::vector<std::pair<std::vector<std::string>, Node>> pairs =
425	      convertQFLIAToMatrices(lambda);
426	
427	  // Build the cones and the star constraints over all of them.
428	  auto [cones, starConstraints] = getCones(literal, pairs);
429	
430	  if (TraceIsOn("liastar-ext-smt"))
431	  {
432	    // Debug only: build the per-cone membership encoding (v in S, a single
433	    // element) and emit (check-sat) queries asserting it is equivalent to the
434	    // predicate, so a separate solver run can validate the cone decomposition.
435	    // The actual lemma below uses `starConstraints`, not `lia`.
436	    std::vector<std::pair<Node, Node>> lia =
437	        getMembershipDisjuncts(lambda, cones);
438	    Trace("liastar-ext") << "lia constraint: " << std::endl;
439	    traceMembershipValidation(d_nm, lambda, lia);
440	  }
441	  Node star = d_nm->mkNode(Kind::AND, starConstraints);
442	  Trace("liastar-ext") << "starConstraints: " << std::endl
443	                       << toString(starConstraints) << std::endl;
444	  star = rewrite(star);
