613	    // Use Normaliz itself as the satisfiability oracle (the conjunction is a
614	    // single cone; an empty cone means unsat).
615	    Node variables = nm->mkNode(Kind::BOUND_VAR_LIST, freeVariables);
616	    assertion = expr::algorithm::flatten(nm, assertion);
617	    return normalizCheckSat(variables, assertion);
618	  }
619	  else
