626	Node LiaStarUtils::getDisjunct(Node assertion,
627	                               const std::vector<Node>& from,
628	                               const std::vector<Node>& to,
629	                               Env* e,
630	                               SolverEngine* smte)
631	{
632	  NodeManager* nm = e->getNodeManager();
633	  // The subsolver `smte` already has `assertion` (and the negations of the
634	  // previously discovered cone-disjuncts) asserted; we only check it and read
635	  // the model. `assertion` is passed here only to enumerate the atoms whose
636	  // truth value the disjunct fixes.
637	  Result result = smte->checkSat();
638	  if (result.getStatus() == Result::Status::UNSAT)
639	  {
640	    // No region of the predicate is left uncovered: the cone encoding is exact.
641	    return nm->mkConst<>(false);
642	  }
643	  // Build one disjunct of the satisfying region by fixing every atom of the
644	  // formula to its truth value in the model. The result is a conjunction of
645	  // literals that implies the formula. We deliberately do not read the
646	  // arithmetic theory's facts: the linear solver eliminates variables using
647	  // equalities, so those equalities would be missing from the facts and the
648	  // resulting cone would be too coarse.
649	  std::vector<Node> atoms;
650	  std::unordered_set<Node> visited;
651	  collectAtoms(assertion, atoms, visited);
652	  std::vector<Node> literals;
653	  for (const Node& atom : atoms)
654	  {
655	    Node literal;
656	    if (smte->getValue(atom).getConst<bool>())
657	    {
658	      // the atom is true in the model: keep it as is
659	      literal = atom;
660	    }
661	    else if (atom.getKind() == Kind::EQUAL && atom[0].getType().isInteger())
662	    {
663	      // A disequality is not convex (it is the union of two half-spaces), so it
664	      // cannot be a single cone. Pick the strict inequality on the side that
665	      // the model satisfies.
666	      Rational lhs = smte->getValue(atom[0]).getConst<Rational>();
667	      Rational rhs = smte->getValue(atom[1]).getConst<Rational>();
668	      Kind k = lhs > rhs ? Kind::GT : Kind::LT;
669	      literal = nm->mkNode(k, atom[0], atom[1]);
670	    }
671	    else
672	    {
673	      // the atom is false in the model: negate it
674	      literal = atom.notNode();
675	    }
676	    if (!from.empty())
677	    {
678	      // substitute the fresh constants back to the lambda's bound variables.
679	      literal =
680	          literal.substitute(to.begin(), to.end(), from.begin(), from.end());
681	    }
682	    literals.push_back(literal);
683	  }
684	  if (literals.empty())
685	  {
686	    return nm->mkConst<>(true);
687	  }
688	  if (literals.size() == 1)
689	  {
690	    return literals[0];
691	  }
692	  return nm->mkNode(Kind::AND, literals);
693	}
