700	  // the accumulated lambdas on each call. Start from the persisted per-cone
701	  // constraints and append the freshly built sum constraints, leaving
702	  // `d_starConstraints` holding only the per-cone constraints.
703	  std::vector<Node> result = starConstraints;
704	  std::vector<Node> sums = buildSumConstraints(d_nm, d_zero, vec, lambdas);
